import re

def cmp_semver(a, b):
    def parse_version(v):
        # Split off build metadata
        if '+' in v:
            v = v.split('+', 1)[0]
        # Split off pre-release
        if '-' in v:
            # Find the first '-' that separates version from pre-release
            # The version part is before the first '-' that is not part of the version numbers
            # Actually, in SemVer, the pre-release is after the first '-' following the patch
            # So we split on the first '-'
            parts = v.split('-', 1)
            version_part = parts[0]
            prerelease_part = parts[1]
        else:
            version_part = v
            prerelease_part = None

        # Parse major.minor.patch
        match = re.match(r'^(\d+)\.(\d+)\.(\d+)$', version_part)
        if not match:
            raise ValueError(f"Invalid version string: {v}")
        major, minor, patch = int(match.group(1)), int(match.group(2)), int(match.group(3))

        return (major, minor, patch, prerelease_part)

    def compare_prerelease(pre_a, pre_b):
        # If both are None, they are equal
        if pre_a is None and pre_b is None:
            return 0
        # If one is None, the one with pre-release sorts before
        if pre_a is None:
            return 1  # a has no pre-release, b has pre-release -> a > b
        if pre_b is None:
            return -1  # a has pre-release, b has no pre-release -> a < b

        # Both have pre-release
        ids_a = pre_a.split('.')
        ids_b = pre_b.split('.')

        for id_a, id_b in zip(ids_a, ids_b):
            # Check if numeric
            is_num_a = id_a.isdigit()
            is_num_b = id_b.isdigit()

            if is_num_a and is_num_b:
                num_a = int(id_a)
                num_b = int(id_b)
                if num_a < num_b:
                    return -1
                elif num_a > num_b:
                    return 1
            elif is_num_a and not is_num_b:
                # Numeric identifiers always have lower precedence than alphanumeric
                return -1
            elif not is_num_a and is_num_b:
                return 1
            else:
                # Both alphanumeric, compare lexically
                if id_a < id_b:
                    return -1
                elif id_a > id_b:
                    return 1

        # All compared identifiers are equal, longer list wins
        if len(ids_a) < len(ids_b):
            return -1
        elif len(ids_a) > len(ids_b):
            return 1
        else:
            return 0

    major_a, minor_a, patch_a, pre_a = parse_version(a)
    major_b, minor_b, patch_b, pre_b = parse_version(b)

    # Compare major
    if major_a < major_b:
        return -1
    elif major_a > major_b:
        return 1

    # Compare minor
    if minor_a < minor_b:
        return -1
    elif minor_a > minor_b:
        return 1

    # Compare patch
    if patch_a < patch_b:
        return -1
    elif patch_a > patch_b:
        return 1

    # Compare pre-release
    return compare_prerelease(pre_a, pre_b)
