def parse_range(header, size):
    """
    Parse an HTTP Range header for bytes according to RFC 7233.

    Args:
        header: The Range header value (e.g., "bytes=0-499")
        size: The total size of the resource in bytes

    Returns:
        A list of (start, end) inclusive byte offsets, or None if unsatisfiable/malformed.
    """
    if not header or not isinstance(header, str):
        return None

    # Check for "bytes=" prefix
    if not header.startswith("bytes="):
        return None

    range_spec = header[6:]  # Remove "bytes="

    if not range_spec:
        return None

    # Split by comma to get individual ranges
    ranges = [r.strip() for r in range_spec.split(",")]

    if not ranges:
        return None

    parsed_ranges = []

    for r in ranges:
        if not r:
            return None

        # Parse the range
        if "-" not in r:
            return None

        parts = r.split("-", 1)
        start_str = parts[0].strip()
        end_str = parts[1].strip()

        if start_str == "" and end_str == "":
            return None

        # Handle suffix range: bytes=-500
        if start_str == "":
            # Suffix range: last N bytes
            try:
                suffix_len = int(end_str)
            except ValueError:
                return None
            if suffix_len <= 0:
                return None
            # Last suffix_len bytes
            start = max(0, size - suffix_len)
            end = size - 1
            if start > end:
                # Suffix length larger than resource yields whole resource
                start = 0
                end = size - 1
            parsed_ranges.append((start, end))
        elif end_str == "":
            # Open-ended range: bytes=500-
            try:
                start = int(start_str)
            except ValueError:
                return None
            if start < 0:
                return None
            if start >= size:
                # Unsatisfiable
                continue
            end = size - 1
            parsed_ranges.append((start, end))
        else:
            # Explicit range: bytes=0-499
            try:
                start = int(start_str)
                end = int(end_str)
            except ValueError:
                return None
            if start < 0 or end < 0:
                return None
            if start > end:
                return None
            if start >= size:
                # Unsatisfiable
                continue
            # Clamp end to size - 1
            end = min(end, size - 1)
            if start > end:
                continue
            parsed_ranges.append((start, end))

    if not parsed_ranges:
        return None

    return parsed_ranges
