class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.key_to_val = {}
        self.key_to_freq = {}
        # freq -> OrderedDict of keys (most recently used at end)
        self.freq_to_keys = {}
        self.min_freq = 0

    def get(self, key: int) -> int:
        if key not in self.key_to_val:
            return -1
        self._increase_freq(key)
        return self.key_to_val[key]

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return
        if key in self.key_to_val:
            self.key_to_val[key] = value
            self._increase_freq(key)
        else:
            if len(self.key_to_val) >= self.capacity:
                self._evict()
            self.key_to_val[key] = value
            self.key_to_freq[key] = 1
            if 1 not in self.freq_to_keys:
                self.freq_to_keys[1] = {}
            self.freq_to_keys[1][key] = None
            self.min_freq = 1

    def _increase_freq(self, key: int) -> None:
        old_freq = self.key_to_freq[key]
        new_freq = old_freq + 1
        self.key_to_freq[key] = new_freq

        # Remove from old freq bucket
        del self.freq_to_keys[old_freq][key]
        if not self.freq_to_keys[old_freq]:
            del self.freq_to_keys[old_freq]
            if self.min_freq == old_freq:
                self.min_freq = new_freq

        # Add to new freq bucket
        if new_freq not in self.freq_to_keys:
            self.freq_to_keys[new_freq] = {}
        self.freq_to_keys[new_freq][key] = None

    def _evict(self) -> None:
        # Evict the least recently used key from the min_freq bucket
        freq = self.min_freq
        keys_dict = self.freq_to_keys[freq]
        # The first key in the dict is the least recently used
        evict_key = next(iter(keys_dict))
        del keys_dict[evict_key]
        if not keys_dict:
            del self.freq_to_keys[freq]
        del self.key_to_val[evict_key]
        del self.key_to_freq[evict_key]
