import re

def parse_duration(s: str) -> float:
    if not s:
        raise ValueError("Empty duration string")

    # Check for leading minus sign
    negative = False
    if s.startswith('-'):
        negative = True
        s = s[1:]

    if not s.startswith('P'):
        raise ValueError("Duration must start with 'P'")

    # Split into date and time parts
    if 'T' in s:
        date_part = s[1:s.index('T')]
        time_part = s[s.index('T')+1:]
        has_time = True
    else:
        date_part = s[1:]
        time_part = ''
        has_time = False

    # If there's a T but no time part, that's invalid
    if has_time and not time_part:
        raise ValueError("T present but no time fields")

    # If no T, time_part should be empty
    if not has_time:
        time_part = ''

    # Parse date part: nYnMnD
    years = 0
    months = 0
    days = 0

    if date_part:
        # Match patterns like 1Y, 2M, 3D
        date_pattern = re.compile(r'(\d+)Y|(\d+)M|(\d+)D')
        pos = 0
        for match in date_pattern.finditer(date_part):
            if match.start() != pos:
                raise ValueError(f"Invalid date part: {date_part}")
            pos = match.end()
            if match.group(1) is not None:
                years = int(match.group(1))
            elif match.group(2) is not None:
                months = int(match.group(2))
            elif match.group(3) is not None:
                days = int(match.group(3))
        if pos != len(date_part):
            raise ValueError(f"Invalid date part: {date_part}")

    # Parse time part: nHnMnS
    hours = 0
    minutes = 0
    seconds = 0.0

    if time_part:
        # Match patterns like 1H, 2M, 3.4S
        time_pattern = re.compile(r'(\d+)H|(\d+)M|(\d+(?:\.\d+)?)S')
        pos = 0
        for match in time_pattern.finditer(time_part):
            if match.start() != pos:
                raise ValueError(f"Invalid time part: {time_part}")
            pos = match.end()
            if match.group(1) is not None:
                hours = int(match.group(1))
            elif match.group(2) is not None:
                minutes = int(match.group(2))
            elif match.group(3) is not None:
                seconds = float(match.group(3))
        if pos != len(time_part):
            raise ValueError(f"Invalid time part: {time_part}")

    # Check that at least one field is present
    if years == 0 and months == 0 and days == 0 and hours == 0 and minutes == 0 and seconds == 0:
        raise ValueError("At least one field must be present")

    # Convert to seconds
    total_seconds = (
        years * 365 * 24 * 3600 +
        months * 30 * 24 * 3600 +
        days * 24 * 3600 +
        hours * 3600 +
        minutes * 60 +
        seconds
    )

    if negative:
        total_seconds = -total_seconds

    return float(total_seconds)
