import datetime
import re


def parse_field(field, min_val, max_val, field_name):
    """Parse a single cron field and return a set of valid integer values."""
    if field == '*':
        return set(range(min_val, max_val + 1))

    values = set()
    parts = field.split(',')

    for part in parts:
        # Check for step
        if '/' in part:
            range_part, step_str = part.split('/', 1)
            try:
                step = int(step_str)
            except ValueError:
                raise ValueError(f"Invalid step in {field_name} field: {part}")
            if step <= 0:
                raise ValueError(f"Step must be positive in {field_name} field: {part}")
        else:
            range_part = part
            step = 1

        # Parse range part
        if range_part == '*':
            start, end = min_val, max_val
        elif '-' in range_part:
            try:
                start_str, end_str = range_part.split('-', 1)
                start = int(start_str)
                end = int(end_str)
            except ValueError:
                raise ValueError(f"Invalid range in {field_name} field: {part}")
        else:
            try:
                start = int(range_part)
                end = start
            except ValueError:
                raise ValueError(f"Invalid value in {field_name} field: {part}")

        # Validate bounds
        if start < min_val or end > max_val:
            raise ValueError(f"Value out of range in {field_name} field: {part}")
        if start > end:
            raise ValueError(f"Invalid range in {field_name} field: {part}")

        # Generate values
        for v in range(start, end + 1, step):
            values.add(v)

    if not values:
        raise ValueError(f"No valid values in {field_name} field: {field}")

    return values


def next_fire(expr, after):
    """
    Return the next datetime strictly after `after` at which the cron expression fires.
    expr: 5-field cron expression (minute hour day-of-month month day-of-week)
    after: datetime object
    """
    if not isinstance(after, datetime.datetime):
        raise ValueError("after must be a datetime object")

    fields = expr.strip().split()
    if len(fields) != 5:
        raise ValueError("Cron expression must have exactly 5 fields")

    minute_field, hour_field, dom_field, month_field, dow_field = fields

    # Parse each field
    minutes = parse_field(minute_field, 0, 59, "minute")
    hours = parse_field(hour_field, 0, 23, "hour")
    doms = parse_field(dom_field, 1, 31, "day-of-month")
    months = parse_field(month_field, 1, 12, "month")
    dows = parse_field(dow_field, 0, 6, "day-of-week")

    # Determine if dom and dow are restricted (not '*')
    dom_restricted = dom_field != '*'
    dow_restricted = dow_field != '*'

