import heapq

def topo_lex(graph):
    """
    graph: dict mapping node -> list of nodes that depend on it (successors)
    Returns lexicographically smallest topological ordering, or None if cycle exists.
    """
    # Collect all nodes (including those only appearing as successors)
    all_nodes = set()
    for node in graph:
        all_nodes.add(node)
        for succ in graph[node]:
            all_nodes.add(succ)

    # Build in-degree map and adjacency list
    # in_degree[node] = number of predecessors (nodes that have this node as a successor)
    in_degree = {node: 0 for node in all_nodes}
    adj = {node: [] for node in all_nodes}

    for node in graph:
        for succ in graph[node]:
            adj[node].append(succ)
            in_degree[succ] += 1

    # Initialize heap with all nodes having in_degree 0
    heap = []
    for node in all_nodes:
        if in_degree[node] == 0:
            heapq.heappush(heap, node)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for succ in adj[node]:
            in_degree[succ] -= 1
            if in_degree[succ] == 0:
                heapq.heappush(heap, succ)

    if len(result) != len(all_nodes):
        return None

    return result
