function sqlTag(strings, ...values) {
  const result = { text: '', values: [] };
  let placeholderCount = 0;

  for (let i = 0; i < strings.length; i++) {
    result.text += strings[i];

    if (i < values.length) {
      const value = values[i];

      if (value && typeof value === 'object' && 'text' in value && 'values' in value && Array.isArray(value.values)) {
        // It's a sqlTag result: inline it
        const subText = value.text;
        const subValues = value.values;
        const subPlaceholderCount = subValues.length;

        // Renumber placeholders in subText from $1, $2, ... to $(placeholderCount+1), $(placeholderCount+2), ...
        let renumberedText = subText;
        for (let j = subPlaceholderCount; j >= 1; j--) {
          const oldPlaceholder = '$' + j;
          const newPlaceholder = '$' + (placeholderCount + j);
          // Replace all occurrences of oldPlaceholder with newPlaceholder
          // We need to be careful not to replace parts of other placeholders.
          // Since placeholders are $1, $2, etc., and we process from highest to lowest,
          // we can safely replace.
          renumberedText = renumberedText.split(oldPlaceholder).join(newPlaceholder);
        }

        result.text += renumberedText;
        result.values.push(...subValues);
        placeholderCount += subPlaceholderCount;
      } else if (Array.isArray(value)) {
        // Array: parenthesised comma-separated list of placeholders
        const placeholders = value.map(() => {
          placeholderCount++;
          return '$' + placeholderCount;
        });
        result.text += '(' + placeholders.join(', ') + ')';
        result.values.push(...value);
      } else {
        // Single value: positional placeholder
        placeholderCount++;
        result.text += '$' + placeholderCount;
        result.values.push(value);
      }
    }
  }

  return result;
}

