function chunkAsync(source, size) {
  if (size <= 0) {
    throw new Error('size must be positive');
  }

  async function* generator() {
    const iterator = source[Symbol.asyncIterator]
      ? source[Symbol.asyncIterator]()
      : source[Symbol.iterator]
        ? source[Symbol.iterator]()
        : null;

    if (!iterator) {
      throw new TypeError('source is not iterable');
    }

    let done = false;
    let buffer = [];

    try {
      while (!done) {
        // Pull up to `size` items into the buffer
        while (buffer.length < size) {
          const result = await iterator.next();
          if (result.done) {
            done = true;
            break;
          }
          buffer.push(result.value);
        }

        // Yield the buffer if it has items
        if (buffer.length > 0) {
          yield buffer;
          buffer = [];
        }
      }
    } finally {
      // Call return() on the source iterator if it exists
      if (typeof iterator.return === 'function') {
        await iterator.return();
      }
    }
  }

  return generator();
}

module.exports = chunkAsync;
