function toposortTasks(tasks) {
  const names = Object.keys(tasks);
  const nameSet = new Set(names);

  // Validate dependencies
  for (const name of names) {
    const deps = tasks[name].deps || [];
    for (const dep of deps) {
      if (!nameSet.has(dep)) {
        return Promise.reject(new Error(`Unknown dependency: ${dep}`));
      }
    }
  }

  // Detect cycles using DFS
  const WHITE = 0, GRAY = 1, BLACK = 2;
  const color = {};
  for (const name of names) {
    color[name] = WHITE;
  }

  function hasCycle(node) {
    color[node] = GRAY;
    const deps = tasks[node].deps || [];
    for (const dep of deps) {
      if (color[dep] === GRAY) {
        return true;
      }
      if (color[dep] === WHITE && hasCycle(dep)) {
        return true;
      }
    }
    color[node] = BLACK;
    return false;
  }

  for (const name of names) {
    if (color[name] === WHITE) {
      if (hasCycle(name)) {
        return Promise.reject(new Error('Dependency cycle detected'));
      }
    }
  }

  // Compute in-degrees and reverse adjacency (dependents)
  const inDegree = {};
  const dependents = {};
  for (const name of names) {
    inDegree[name] = 0;
    dependents[name] = [];
  }
  for (const name of names) {
    const deps = tasks[name].deps || [];
    inDegree[name] = deps.length;
    for (const dep of deps) {
      dependents[dep].push(name);
    }
  }

  const results = {};
  const completed = new Set();
  const failed = new Set();
  let firstError = null;

  // Queue of tasks ready to run (in-degree 0 and not failed)
  const readyQueue = [];
  for (const name of names) {
    if (inDegree[name] === 0) {
      readyQueue.push(name);
    }
  }

  const pendingPromises = new Map(); // name -> promise

  function runTask(name) {
    const task = tasks[name];
    const deps = task.deps || [];
    const depValues = {};
    for (const dep of deps) {
      depValues[dep] = results[dep];
    }

    const promise = Promise.resolve()
      .then(() => task.run(depValues))
      .then((value) => {
        results[name] = value;
        completed.add(name);
        // Decrement in-degree of dependents
        for (const dependent of dependents[name]) {
          inDegree[dependent]--;
          if (inDegree[dependent] === 0 && !failed.has(dependent)) {
            // Check if any dependency failed
            const depsOfDependent = tasks[dependent].deps || [];
            const anyFailed = depsOfDependent.some(d => failed.has(d));
            if (!anyFailed) {
              readyQueue.push(dependent);
            } else {
              failed.add(dependent);
              // Propagate failure to dependents
              propagateFailure(dependent);
            }
          }
        }
        return value;
      })
      .catch((err) => {
        failed.add(name);
        if (!firstError) {
          firstError = err;
        }
        // Propagate failure to dependents
        propagateFailure(name);
        throw err;
      });

    pendingPromises.set(name, promise);
    return promise;
  }

  function propagateFailure(name) {
    for (const dependent of dependents[name]) {
      if (!failed.has(dependent)) {
        failed.add(dependent);
        if (!firstError) {
          firstError = new Error(`Task ${dependent} failed due to dependency ${name}`);
        }
        propagateFailure(dependent);
      }
    }
  }

  return new Promise((resolve, reject) => {
    let running = 0;
    let totalTasks = names.length;
    let settled = 0;

    function checkDone() {
      if (settled === totalTasks) {
        if (firstError) {
          reject(firstError);
        } else {
          resolve(results);
        }
      }
    }

    function processQueue() {
      while (readyQueue.length > 0) {
        const name = readyQueue.shift();
        if (failed.has(name)) continue;
        running++;
        const promise = runTask(name);
        promise.then(() => {
          running--;
          settled++;
          checkDone();
          processQueue();
        }).catch(() => {
          running--;
          settled++;
          checkDone();
          processQueue();
        });
      }
      // If no tasks are running and queue is empty but not all settled, check for deadlock
      if (running === 0 && readyQueue.length === 0 && settled < totalTasks) {
        // This shouldn't happen if cycle detection worked, but just in case
        if (firstError) {
          reject(firstError);
        } else {
          reject(new Error('Deadlock detected'));
        }
      }
    }

    processQueue();
  });
}

