type EventMap = Record<string, unknown>;

type Handler<E extends EventMap, K extends keyof E> = (payload: E[K]) => void;

type Unsubscribe = () => void;

export class Bus<E extends EventMap> {
  private handlers: Map<keyof E, Set<Handler<E, keyof E>>> = new Map();

  on<K extends keyof E>(event: K, handler: Handler<E, K>): Unsubscribe {
    if (!this.handlers.has(event)) {
      this.handlers.set(event, new Set());
    }
    const set = this.handlers.get(event)!;
    set.add(handler as Handler<E, keyof E>);
    return () => {
      set.delete(handler as Handler<E, keyof E>);
    };
  }

  emit<K extends keyof E>(
    event: K,
    ...args: E[K] extends void ? [] : [payload: E[K]]
  ): void {
    const set = this.handlers.get(event);
    if (!set) return;
    const payload = args[0] as E[K];
    for (const handler of set) {
      (handler as Handler<E, K>)(payload);
    }
  }
}
