  const handler: ProxyHandler<BuilderState<Config>> = {
    get(_target, prop: string | symbol) {
      if (prop === 'set') {
        return (key: string, value: unknown) => {
          (data as any)[key] = value;
          return new Proxy({}, handler) as any;
        };
      }
      if (prop === 'build') {
        return () => {
          return { ...data } as Config;
        };
      }
      return undefined;
    }
  };

  return new Proxy({} as BuilderState<Config>, handler);
}
