// UnionToIntersection: converts a union type to an intersection type
export type UnionToIntersection<U> = (U extends any ? (k: U) => void : never) extends (k: infer I) => void ? I : never;

// IsUnion: returns true only if T is a genuine union (more than one member)
// For a single type or never, returns false.
// For boolean (true | false), returns true.
export type IsUnion<T, B = T> = T extends B
  ? [B] extends [T]
    ? false
    : true
  : never;

// LastOf: gets the last member of a union by using the fact that
// UnionToIntersection of a union of function types that take each member
// as a parameter, when inferred, gives the last one due to contravariance.
// Actually, the standard trick: UnionToIntersection of (U extends any ? (x: U) => void : never)
// gives an intersection of functions, and inferring the parameter gives the last member.
export type LastOf<U> = UnionToIntersection<U extends any ? (x: U) => void : never> extends (x: infer L) => void ? L : never;

// UnionToTuple: converts a union to a tuple of its members.
// This is tricky because unions are unordered. The standard approach uses
// LastOf recursively. However, this relies on the order in which TypeScript
// resolves the union, which is not guaranteed but works in practice for
// simple unions. For boolean, it should produce [true, false] or [false, true]
// depending on internal ordering. The requirement says boolean must not collapse
// incorrectly, meaning it should be treated as a union of two members.
// We use a recursive approach: get the last member, then recurse on the rest.

type UnionToTupleHelper<U, Result extends unknown[] = []> = [U] extends [never]
  ? Result
  : UnionToTupleHelper<Exclude<U, LastOf<U>>, [LastOf<U>, ...Result]>;

export type UnionToTuple<U> = UnionToTupleHelper<U>;
